from collections import defaultdict

def lines(I, direction):
    n=len(I); m=len(I[0]); L=defaultdict(set)
    for r in range(n):
        for c in range(m):
            if I[r][c]:
                k={'row':r,'col':c,'diag':c-r,'adiag':c+r}[direction]
                L[k].add(I[r][c])
    return {k:list(v)[0] for k,v in L.items() if len(v)==1}, any(len(v)>1 for v in L.values())

def transform(g):
    for d in ('row','col','diag','adiag'):
        lm, bad = lines(g, d)
        if lm and not bad:
            p=max(lm)+1 if d in('row','col') else None
            ks=sorted(lm)
            # minimal period p such that keys have distinct residues
            for p in range(1, 61):
                if len({k%p for k in lm})==len(lm): break
            seq={k%p:v for k,v in lm.items()}
            n,m=len(g),len(g[0])
            return [[seq[({'row':r,'col':c,'diag':c-r,'adiag':c+r}[d])%p] for c in range(m)] for r in range(n)]

for k in ['Demo pair 1','Demo pair 2']:
